def prices_ref(s):
    lines = s.split('\n'); n = int(lines[0]); book = {}
    for line in lines[1:n + 1]:
        name, price = line.split(); book[name] = price
    q = int(lines[n + 1])
    return '\n'.join(book.get(name.strip(), '-1') for name in lines[n + 2:n + 2 + q])
def price_case():
    names = [word('abcdefg', 1, 4) for _ in range(6)]
    items = [(R.choice(names), R.randrange(0, 1000)) for _ in range(6)]
    queries = [R.choice(names) for _ in range(5)]
    return rows(str(len(items)), *[f'{a} {b}' for a, b in items], str(len(queries)), *queries)
