def min_window_ref(s):
    v = ints(s); n, target = v[:2]; a = v[2:]
    lengths = [j - i for i in range(n) for j in range(i + 1, n + 1) if sum(a[i:j]) >= target]
    return min(lengths) if lengths else 0
