def random_brackets(pairs):
    out, opened, left = [], 0, pairs
    while left or opened:
        if left and (not opened or R.random() < 0.5):
            out.append('('); left -= 1; opened += 1
        else:
            out.append(')'); opened -= 1
    return ''.join(out)
def depth_ref(s):
    s = s.strip(); return max(s[:i].count('(') - s[:i].count(')') for i in range(len(s) + 1))
