def change_ref(s):
    n = int(s); best = [0] * 2000
    for x in range(1, 2000):
        best[x] = 1 + min(best[x - c] for c in (1, 2, 5, 10) if c <= x)
    k = max(0, (n - 1000) // 10)  # для больших сумм оптимальный ответ содержит все эти десятки
    return k + best[n - 10 * k]
