def climb_ref(s):
    v = ints(s); n = v[0]; cost = [0] + v[1:]
    def paths(i):
        if i == n:
            yield 0; return
        for jump in (1, 2):
            if i + jump <= n:
                for rest in paths(i + jump): yield cost[i + jump] + rest
    return min(paths(0))
