# 23. Динамика на минимум: монеты
def reach_ref(s):
    v = ints(s); target = v[1]; coins = v[2:]; seen = {0}; frontier = [0]
    while frontier:
        nxt = []
        for x in frontier:
            for c in coins:
                if x + c <= target and x + c not in seen:
                    seen.add(x + c); nxt.append(x + c)
        frontier = nxt
    return 'YES' if target in seen else 'NO'
