def jumps_ref(s):
    v = ints(s); target = v[1]; jumps = v[2:]; ways = [0] * (target + 1); ways[0] = 1
    for x in range(target):
        for c in jumps:
            if x + c <= target: ways[x + c] = (ways[x + c] + ways[x]) % 1000000007
    return ways[target]
