# 25. Графы: BFS
def dist_ref(s):
    v = ints(s); n = v[0]; d = [[math.inf] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1): d[i][i] = 0
    for a, b in zip(v[2::2], v[3::2]):
        if a != b: d[a][b] = d[b][a] = 1
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    return ' '.join(str(-1 if d[1][j] == math.inf else d[1][j]) for j in range(1, n + 1))
