def knight_ref(s):
    v = ints(s); n = v[0]; x1, y1, x2, y2 = v[1:]
    d = {(x, y): math.inf for x in range(1, n + 1) for y in range(1, n + 1)}; d[x1, y1] = 0
    moves = [(a, b) for a in (-2, -1, 1, 2) for b in (-2, -1, 1, 2) if abs(a) != abs(b)]
    changed = True
    while changed:  # релаксация до неподвижной точки, независимо от BFS
        changed = False
        for (x, y), dv in list(d.items()):
            for a, b in moves:
                c = (x + a, y + b)
                if c in d and d[c] > dv + 1:
                    d[c] = dv + 1; changed = True
    return -1 if d[x2, y2] == math.inf else d[x2, y2]
