# 26. Графы: DFS
def reach_case(n, s, t, edges): return f'{n} {len(edges)} {s} {t}\n' + ''.join(f'{u} {w}\n' for u, w in edges)
def reach_graph_ref(s):
    v = ints(s); n, a, b = v[0], v[2], v[3]; parent = list(range(n + 1))
    def find(x):
        while parent[x] != x: x = parent[x]
        return x
    for u, w in zip(v[4::2], v[5::2]): parent[find(u)] = find(w)
    return 'YES' if find(a) == find(b) else 'NO'
