def islands_ref(s):
    lines = s.split('\n'); n, m = map(int, lines[0].split()); g = lines[1:n + 1]
    parent = {(i, j): (i, j) for i in range(n) for j in range(m) if g[i][j] == '#'}
    def find(x):
        while parent[x] != x: x = parent[x]
        return x
    for i, j in list(parent):
        for c in ((i + 1, j), (i, j + 1)):
            if c in parent: parent[find(c)] = find((i, j))
    return len({find(c) for c in parent})
def island_case(n, m): return rows(f'{n} {m}', *[''.join('#' if R.random() < 0.45 else '.' for _ in range(m)) for _ in range(n)])
