# 27. Взвешенные графы
def ropes_merge_ref(s):
    @functools.lru_cache(None)
    def best(t):
        if len(t) <= 1: return 0
        options = []
        for i, j in itertools.combinations(range(len(t)), 2):
            rest = tuple(sorted(t[:i] + t[i + 1:j] + t[j + 1:] + (t[i] + t[j],)))
            options.append(t[i] + t[j] + best(rest))
        return min(options)
    return best(tuple(sorted(ints(s)[1:])))
