def matrix_case(n, roads):
    c = [[0 if i == j else -1 for j in range(n)] for i in range(n)]
    for a, b, w in roads: c[a][b] = c[b][a] = w
    return rows(str(n), *[' '.join(map(str, row)) for row in c])
def matrix_ref(s):
    v = ints(s); n = v[0]; c = [v[1 + i * n:1 + (i + 1) * n] for i in range(n)]
    d = [[math.inf if c[i][j] == -1 else c[i][j] for j in range(n)] for i in range(n)]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    return ' '.join(str(-1 if x == math.inf else x) for x in d[0])
