# 28. DSU
def groups_ref(s):
    v = ints(s); n = v[0]; adj = collections.defaultdict(set)
    for a, b in zip(v[2::2], v[3::2]): adj[a].add(b); adj[b].add(a)
    seen, count = set(), 0
    for start in range(1, n + 1):
        if start in seen: continue
        count += 1; todo = [start]; seen.add(start)
        while todo:
            for y in adj[todo.pop()]:
                if y not in seen: seen.add(y); todo.append(y)
    return count
