def cycle_edge_ref(s):
    v = ints(s); adj = collections.defaultdict(set)
    for i, (a, b) in enumerate(zip(v[2::2], v[3::2]), 1):
        seen = {a}; todo = [a]
        while todo:
            for y in adj[todo.pop()]:
                if y not in seen: seen.add(y); todo.append(y)
        if b in seen: return i
        adj[a].add(b); adj[b].add(a)
    return 0
