# 29. Дерево Фенвика
def prefix_queries_case(a, qs): return f'{len(a)} {len(qs)}\n' + ' '.join(map(str, a)) + '\n' + ''.join(f'{i}\n' for i in qs)
def prefix_queries_ref(s):
    v = ints(s); n = v[0]; a = v[2:2 + n]
    return '\n'.join(str(sum(a[:i])) for i in v[2 + n:])
