def expand_practice(lessons):
    mains = [l for l in lessons if l['day']]
    assert set(STEPS) == {l['id'] for l in mains} and all(len(v) == 2 for v in STEPS.values())
    for main in mains:
        for rung, s in enumerate(STEPS[main['id']], 1):
            tests = [{'input': case, 'expected': str(s['oracle'](case)).strip(), 'label': 'Пример' if i == 0 else 'Граничный случай' if i < 4 else 'Дополнительный тест'} for i, case in enumerate(s['cases'])]
            lessons.append(dict(id=f"step-{main['id']}-{rung}", parent=main['id'], rung=rung, title=s['title'], topic=main['topic'], day=0, level='Ступенька', minutes=10 if rung == 1 else 15,
                theory=s['theory'], example=s['example'], task=s['task'], inputs=s['inputs'], output=s['output'], starter=s['starter'], solution=s['solution'],
                hints=s['hints'], explain=s['explain'], complexity=s['complexity'], trap=s['trap'],
                quiz=dict(question=s['quiz'][0], options=s['quiz'][1], answer=s['quiz'][2], explanation=s['quiz'][3]), tests=tests,
                practice=dict(goal=s['goal'], walk=s['walk'], terms=[list(t) for t in s['terms']]), lineNotes=line_notes(s['solution'])))
